-- Same category, two spellings.
update public.recipes
set clasificacion = jsonb_set(clasificacion, '{categoria}', '"bowls"')
where clasificacion ->> 'categoria' = 'bowl';

update public.recipes
set clasificacion = jsonb_set(clasificacion, '{categoria}', '"verdura"')
where clasificacion ->> 'categoria' = 'vegetal';

-- Breakfast recipes tagged `ensalada` whose own name says what they are.
update public.recipes
set clasificacion = jsonb_set(
  clasificacion,
  '{categoria}',
  to_jsonb(
    case
      when nombre ~* '^(bol|boles|bowl|compota|gachas|muesli|porridge|pudding)\M' then 'bowls'
      when nombre ~* '^(batido|smoothie|zumo)\M' then 'batidos'
      else 'lacteos'
    end
  )
)
where clasificacion ->> 'categoria' = 'ensalada'
  and clasificacion ->> 'tipo_plato' = 'desayuno'
  and nombre ~* '^(bol|boles|bowl|compota|gachas|muesli|porridge|pudding|batido|smoothie|zumo|yogur|natillas|skyr)\M';

alter table public.recipes
  add constraint recipes_nombre_sin_con_repetido
  check (nombre !~* '\mcon\M.*\mcon\M');

alter table public.recipes
  add constraint recipes_categoria_en_contrato
  check (
    clasificacion ->> 'categoria' is null
    or clasificacion ->> 'categoria' in ('arroz', 'batidos', 'bowls', 'carne', 'ensalada', 'guiso', 'huevos', 'lacteos', 'legumbres', 'pasta', 'pescado', 'pizza', 'reposteria', 'sandwich', 'sopa', 'tostadas', 'verdura', 'wrap')
  );

comment on constraint recipes_nombre_sin_con_repetido on public.recipes is
  'FRESCO-861. A recipe name cannot repeat the word "con" (generated variants read "X con a con b"; write "X con a y b").';
comment on constraint recipes_categoria_en_contrato on public.recipes is
  'FRESCO-861. clasificacion.categoria must be one of CategoriaReceta (api/schemas/recipe.types.ts); keep both lists in step, tests/db/catalog-titles-and-categories.test.ts compares them.';
